function previewMoney(?int $c): string {return $c===null?'미확인':($c<0?'−'.money(-$c):money($c));}
function previewProductName(?array $current,?array $historical=null): string {
    if($historical) return $historical['name'].' · 과거 용량 '.($historical['weight_g']===null?'미확인':weight($historical['weight_g']));
    return $current?($current['name'].' · 현재 용량 '.weight($current['weight_g'])):'제품·용량 확인 필요';
}
function previewPosition(array $r): string {return $r['sheet'].' 시트 · '.$r['row'].'행';}
function previewLink(array $changes=[]): string {
    $keep=[];foreach(['tab','group','issue','status','q','used','review_group'] as $key) if(is_string($_GET[$key]??null)) $keep[$key]=$_GET[$key];
    return '/?'.http_build_query(array_merge(['page'=>'excel-preview'],$keep,$changes));
}
function previewFlags(array $r): void {
    if(($r['preview_disposition']??'')==='exclude'){echo '<span class="badge">가져오기 제외</span>';return;}
    if(($r['review_disposition']??'')==='hold'){echo '<span class="badge pending">가져오기 보류</span>';return;}
    if(!$r['issues'] && !empty($r['resolved_issues'])){echo '<span class="badge done">그룹 기준 반영</span>';return;}
    if(!$r['issues']) {echo '<span class="badge done">검토 표시 없음</span>';return;}
    echo '<span class="badge pending">확인 '.count($r['issues']).'개</span><small>'.e(reset($r['issues'])).'</small>';
}
$tab=is_string($_GET['tab']??null)?$_GET['tab']:'import';
if(!in_array($tab,['summary','groups','issues','customers','orders','products','import'],true)) $tab='summary';
