<?php else:
 $q=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';
 $issue=is_string($_GET['issue']??null)?$_GET['issue']:'';
 $group=$tab==='issues'?(($_GET['group']??'orders')==='customers'?'customers':'orders'):$tab;
 $status=($_GET['status']??'all')==='review'?'review':'all';
 $used=($_GET['used']??'used')==='all'?'all':'used';
 $selectedGroup=is_string($_GET['review_group']??null)?($report['review_groups'][$_GET['review_group']]??null):null;
 $rows=[];
 foreach($report[$group]??[] as $record) {
    if($selectedGroup && ($selectedGroup['kind']!==$group || !in_array($record['ref'],$selectedGroup['refs'],true)))continue;
    if($tab==='issues' && !$record['issues']) continue;
    if($group!=='products' && ($status==='review' || $tab==='issues') && !$record['issues']) continue;
    if($group!=='products' && $issue!=='' && !isset($record['issues'][$issue])) continue;
    if($group==='products' && $used==='used' && !$record['order_count']) continue;
    $haystack=$group==='customers'?implode(' ',[$record['name'],$record['nickname'],$record['address'],$record['phone'],$record['ref'],$record['contact_name']??'',$record['affiliation']??'']):($group==='orders'?implode(' ',[$record['customer'],$record['date']??'',$record['ref'],implode(' ',array_column($record['items'],'header'))]):implode(' ',[$record['header'],$record['sheet'],$record['column'],$record['historical_product']['name']??$record['current_product']['name']??'']));
    if($q!=='' && !str_contains(previewKey($haystack),previewKey($q))) continue;
    $rows[]=$record;
 }
 $total=count($rows);$pages=max(1,(int)ceil($total/25));$p=min($pages,max(1,(int)($_GET['p']??1)));$display=array_slice($rows,($p-1)*25,25);
