!empty($r['import_as_other'])?'기타 · 원본 제품 정보 보존':previewProductName($prod,$r['historical_product']??null))?><?php if($prod): ?><small>현재 <?=weight($prod['weight_g'])?> · <?=previewMoney($prod['price_cents'])?> · 과거에는 적용하지 않음</small><?php endif ?></td><td><?=$r['order_count']?>행<small>수량 합계 <?=e((string)$r['quantity'])?></small></td><td><?=e($r['reason'])?></td><?php endif ?></tr><?php endforeach ?></tbody></table></div><?php endif ?>
